package com.vignesh.focuslist.ui.component

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * The error mascot: the cat sitting with a question mark above it.
 *
 * The only pose that is not about an empty list. A read failed, so it asks
 * rather than rests, and the question mark is the one prop left in the set:
 * the posture cannot say "something did not load" on its own.
 *
 * Drawn from `cat-hd-error`. It takes the same scale factor as the other six
 * rather than a matching width or height, and it is the tallest of them because
 * the question mark sits clear above the head. [MascotImage] explains why the
 * paths are built in Kotlin and which colour role each tone takes.
 *
 * The question mark takes [dark], the tone the eyes and nose already use, so it
 * reads as part of the drawing rather than as a badge laid over it.
 */
@Composable
internal fun ErrorMascot(modifier: Modifier = Modifier) {
    MascotImage(
        width = MascotWidth,
        height = MascotHeight,
        modifier = modifier,
        build = ::catQuestion
    )
}

private const val MascotWidth = 207.48f
private const val MascotHeight = 228.54f

private fun catQuestion(light: Color, mid: Color, dark: Color): ImageVector =
    ImageVector.Builder(
        name = "ErrorCatQuestion",
        defaultWidth = MascotWidth.dp,
        defaultHeight = MascotHeight.dp,
        viewportWidth = 798f,
        viewportHeight = 879f
    )
        .addPath(
            pathData = addPathNodes(GroundShadow),
            fill = SolidColor(light)
        )
        .addPath(
            pathData = addPathNodes(Body),
            fill = SolidColor(light)
        )
        .addPath(
            pathData = addPathNodes(Tail),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(PawShading1),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(PawShading2),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(Nose),
            fill = SolidColor(dark)
        )
        .addPath(
            pathData = addPathNodes(EyeLeft),
            fill = SolidColor(dark)
        )
        .addPath(
            pathData = addPathNodes(EyeRight),
            fill = SolidColor(dark)
        )
        .addPath(
            pathData = addPathNodes(QuestionMark),
            fill = SolidColor(dark)
        )
        .build()

